-- Metadata snapshots, validation and existing owner RLS. Synthetic owners only.
reset role;
insert into auth.users(id) values('20202020-0000-4000-8000-000000000001'),('20202020-0000-4000-8000-000000000002');
set role authenticated;
set request.jwt.claim.sub='20202020-0000-4000-8000-000000000001';
insert into public.plans(id,name,is_active,template) values('20202020-0000-4000-8000-000000000003','Superset test',true,'ppl');
insert into public.routines(id,plan_id,name,sort_order) values('20202020-0000-4000-8000-000000000004','20202020-0000-4000-8000-000000000003','Upper',0);
insert into public.exercises(id,name,equipment,muscle_groups) select ('20202020-0000-4000-8000-00000000000'||n)::uuid,'Pair test '||n,'dumbbell',array['biceps'] from generate_series(5,8)n;
insert into public.routine_exercises(id,routine_id,exercise_id,sort_order,target_sets,target_reps) select ('20202020-0000-4000-8000-00000000001'||n)::uuid,'20202020-0000-4000-8000-000000000004',('20202020-0000-4000-8000-00000000000'||n)::uuid,n,3,10 from generate_series(5,7)n;
select public.set_superset('routine','20202020-0000-4000-8000-000000000004','20202020-0000-4000-8000-000000000015','20202020-0000-4000-8000-000000000016',90);
insert into public.workouts(id,routine_id) values('20202020-0000-4000-8000-000000000020','20202020-0000-4000-8000-000000000004');
select pg_temp.expect((select supersets->0->>'restSec'='90' from public.workouts where id='20202020-0000-4000-8000-000000000020'),'new planned workout snapshots pair rest');
select public.set_superset('routine','20202020-0000-4000-8000-000000000004','20202020-0000-4000-8000-000000000015',null,90);
select pg_temp.expect((select jsonb_array_length(supersets)=1 from public.workouts where id='20202020-0000-4000-8000-000000000020'),'later plan edit does not change workout pairing');
select pg_temp.expect_error($$select public.set_superset('workout','20202020-0000-4000-8000-000000000020','20202020-0000-4000-8000-000000000017','20202020-0000-4000-8000-000000000016',90)$$,'overlapping supersets rejected');
select pg_temp.expect_error($$select public.set_superset('workout','20202020-0000-4000-8000-000000000020','missing','20202020-0000-4000-8000-000000000016',90)$$,'unknown slots rejected');
select public.set_superset('workout','20202020-0000-4000-8000-000000000020','20202020-0000-4000-8000-000000000015','20202020-0000-4000-8000-000000000016',120,'20202020-0000-4000-8000-000000000004');
select pg_temp.expect((select is_custom from public.plans where id='20202020-0000-4000-8000-000000000003'),'pairing marks a template plan custom');
select pg_temp.expect((select supersets->0->>'restSec'='120' from public.routines where id='20202020-0000-4000-8000-000000000004'),'explicit future save applies to plan');
select public.set_superset('workout','20202020-0000-4000-8000-000000000020','20202020-0000-4000-8000-000000000015','extra:20202020-0000-4000-8000-000000000008',60);
select pg_temp.expect((select supersets->0->>'second'='extra:20202020-0000-4000-8000-000000000008' from public.workouts where id='20202020-0000-4000-8000-000000000020'),'temporary exercise can be paired');
select pg_temp.expect(not public.valid_supersets('[{"first":"a","second":"a","restSec":90}]'),'self pair rejected');
select pg_temp.expect(not public.valid_supersets('[{"first":"a","second":"b","restSec":1.2}]'),'fractional rest rejected');
update public.workouts set ended_at=now() where id='20202020-0000-4000-8000-000000000020';
select public.set_superset('workout','20202020-0000-4000-8000-000000000020','20202020-0000-4000-8000-000000000015','extra:20202020-0000-4000-8000-000000000008',60);
select pg_temp.expect_error($$select public.set_superset('workout','20202020-0000-4000-8000-000000000020','20202020-0000-4000-8000-000000000015',null,90)$$,'finished pairing read only; exact retry allowed');
select pg_temp.expect(public.change_superset('[{"first":"a","second":"b","restSec":90},{"first":"c","second":"d","restSec":60}]','a','b',120)->0->>'first'='a','editing rest retains pair group order');
delete from public.routine_exercises where id='20202020-0000-4000-8000-000000000016';
select pg_temp.expect((select supersets='[]'::jsonb from public.routines where id='20202020-0000-4000-8000-000000000004'),'removing a plan slot unpairs the plan');
select pg_temp.expect((select jsonb_array_length(supersets)=1 from public.workouts where id='20202020-0000-4000-8000-000000000020'),'removing a plan slot retains captured workout pairings');
insert into public.workouts(id,routine_id) values('20202020-0000-4000-8000-000000000021','20202020-0000-4000-8000-000000000004');
select public.set_superset('workout','20202020-0000-4000-8000-000000000021','20202020-0000-4000-8000-000000000015','20202020-0000-4000-8000-000000000017',90);
insert into public.workout_customizations(workout_id,name,source_routine_id,items) values('20202020-0000-4000-8000-000000000021','Custom pair','20202020-0000-4000-8000-000000000004','[{"id":"20202020-0000-4000-8000-000000000015"},{"id":"20202020-0000-4000-8000-000000000017"}]');
update public.workout_customizations set items='[{"id":"20202020-0000-4000-8000-000000000015"}]' where workout_id='20202020-0000-4000-8000-000000000021';
select pg_temp.expect((select supersets='[]'::jsonb from public.workouts where id='20202020-0000-4000-8000-000000000021'),'removing a custom session slot prunes its pairing');
set request.jwt.claim.sub='20202020-0000-4000-8000-000000000002';
select pg_temp.expect((select count(*)=0 from public.workouts where id='20202020-0000-4000-8000-000000000020'),'another owner cannot read pairs');
select pg_temp.expect_error($$select public.set_superset('routine','20202020-0000-4000-8000-000000000004','20202020-0000-4000-8000-000000000015',null,90)$$,'another owner cannot edit plan pairs');
reset role;
select pg_temp.expect(not has_function_privilege('anon','public.set_superset(text,uuid,text,text,integer,uuid)','EXECUTE'),'anonymous pairing RPC revoked');
